import{_ as a,o as i,c as s,al as t}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"Симуляція запобігання відмовам","description":"","frontmatter":{},"headers":[],"relativePath":"uk/simulation/failsafes.md","filePath":"uk/simulation/failsafes.md"}'),n={name:"uk/simulation/failsafes.md"};function l(o,e,r,c,p,d){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="симуляція-запобігання-відмовам" tabindex="-1">Симуляція запобігання відмовам <a class="header-anchor" href="#симуляція-запобігання-відмовам" aria-label="Permalink to &quot;Симуляція запобігання відмовам&quot;">​</a></h1><p><a href="./../config/safety">Failsafes</a> define the safe limits/conditions under which you can safely use PX4, and the action that will be performed if a failsafe is triggered (for example, landing, holding position, or returning to a specified point).</p><p>У SITL деякі запобіжники відмов за замовчуванням вимкнені, щоб забезпечити простіше використання симуляції. Ця тема пояснює, як ви можете перевірити критично важливу для безпеки поведінку в симуляції SITL перед тим, як спробувати її в реальному світі.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You can also test failsafes using <a href="./../simulation/hitl">HITL simulation</a>. HITL використовує нормальні параметри налаштувань вашого контролера польоту.</p></div><h2 id="втрата-каналу-зв-язку" tabindex="-1">Втрата каналу зв&#39;язку <a class="header-anchor" href="#втрата-каналу-зв-язку" aria-label="Permalink to &quot;Втрата каналу зв&#39;язку&quot;">​</a></h2><p>The <em>Data Link Loss</em> failsafe (unavailability of external data via MAVLink) is enabled by default. Це робить симуляцію придатною до використання тільки з під&#39;єднаним GCS, SDK або іншим додатком MAVLink.</p><p>Set the parameter <a href="./../advanced_config/parameter_reference#NAV_DLL_ACT">NAV_DLL_ACT</a> to the desired failsafe action to change the behavior. For example, set to <code>0</code> to disable it.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All parameters in SITL including this one get reset when you do <code>make clean</code>.</p></div><h2 id="втрата-каналу-радіо-керування" tabindex="-1">Втрата каналу радіо керування <a class="header-anchor" href="#втрата-каналу-радіо-керування" aria-label="Permalink to &quot;Втрата каналу радіо керування&quot;">​</a></h2><p>The <em>RC Link Loss</em> failsafe (unavailability of data from a remote control) is enabled by default. Це робить симуляцію придатною до використання тільки з активним з&#39;єднанням MAVLink або дистанційного керування.</p><p>Set the parameter <a href="./../advanced_config/parameter_reference#NAV_RCL_ACT">NAV_RCL_ACT</a> to the desired failsafe action to change the behavior. For example, set to <code>0</code> to disable it.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All parameters in SITL including this one get reset when you do <code>make clean</code>.</p></div><h2 id="низькии-заряд-батареі" tabindex="-1">Низький заряд батареї <a class="header-anchor" href="#низькии-заряд-батареі" aria-label="Permalink to &quot;Низький заряд батареї&quot;">​</a></h2><p>Батарею, що моделюється реалізовано таким чином щоб енергія ніколи не закінчувалась та за замовчуванням вона виснажується тільки до 50% її заряду, а отже і напруги, що доповідається. Це дозволяє тестувати індикацію батареї в GCS Ui без спрацювання реакцій на низький заряд, що може перервати інші тести.</p><p>To change this minimal battery percentage value use the parameter <a href="./../advanced_config/parameter_reference#SIM_BAT_MIN_PCT">SIM_BAT_MIN_PCT</a>.</p><p>To control how fast the battery depletes to the minimal value use the parameter <a href="./../advanced_config/parameter_reference#SIM_BAT_DRAIN">SIM_BAT_DRAIN</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>By changing <a href="./../advanced_config/parameter_reference#SIM_BAT_MIN_PCT">SIM_BAT_MIN_PCT</a> in flight, you can also test regaining capacity to simulate inaccurate battery state estimation or in-air charging technology.</p></div><p>The simulated battery can be completely disabled by setting <a href="./../advanced_config/parameter_reference#SIM_BAT_DRAIN">SIM_BAT_DRAIN</a> to 0. This is useful, for example, if you provide an external battery simulation via MAVLink.</p><h2 id="помилка-датчику-системи" tabindex="-1">Помилка датчику/системи <a class="header-anchor" href="#помилка-датчику-системи" aria-label="Permalink to &quot;Помилка датчику/системи&quot;">​</a></h2><p><a href="./../debug/failure_injection">Failure injection</a> can be used to simulate different types of failures in many sensors and systems. Наприклад, це може бути використано для імітації відсутнього або переривчастого сигналу GPS, сигналу РК який перервався або застиг на певному значенні, збої в системі уникнення, і багато іншого.</p><p>Failure injection is gated by the <a href="./../advanced_config/parameter_reference#SYS_FAILURE_EN">SYS_FAILURE_EN</a> parameter.</p><p>For example, to simulate GPS failure, enter the following commands on the SITL instance <em>pxh shell</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Turn (all) GPS off (no position reported, as for a dead receiver)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Freeze (all) GPS on the last reported position (a &quot;stuck&quot; fix)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stuck</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Report a diverging position (offset by ~111 km, trips the GNSS redundancy checks)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrong</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restore normal GPS output</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ok</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To test the <a href="./../advanced_config/parameter_reference#COM_GNSSLOSS_ACT">GNSS redundancy failsafe</a> you can simulate a second GPS receiver: set the antenna-offset parameter <a href="./../advanced_config/parameter_reference#SENS_GPS1_OFFX">SENS_GPS1_OFFX</a> or <a href="./../advanced_config/parameter_reference#SENS_GPS1_OFFY">SENS_GPS1_OFFY</a> to a non-zero value, and the simulator publishes a second <code>sensor_gps</code> instance offset by that distance (in metres). You can then fail an individual receiver with the <code>-i</code> flag (<code>-i 0</code> = all instances, <code>-i 1</code> = first GPS, <code>-i 2</code> = second), for example <code>failure gps wrong -i 2</code>.</p></div>`,24)])])}const u=a(n,[["render",l]]);export{f as __pageData,u as default};
